26	} from "@/lib/game/config";
27	import { MOB_TEMPLATES } from "@/lib/game/mobs";
28	import { mobsThreaten } from "@/lib/game/gameModes";
29	import { mobDamageMultiplier } from "@/lib/game/difficulties";
30	import type { EmitGameEvent, GameState, MobState } from "../state";
31	import { spawnArrow } from "../projectiles";
32	import { explode } from "./explosion";
33	import { pushMob } from "./spawnDirector";
34	import type { SurfaceYAtFn } from "@/lib/game/spawn";
35	
36	// Scratch vectors — per-frame tick over every mob must not allocate.
37	const UP = new THREE.Vector3(0, 1, 0);
38	const scratchToPlayer = new THREE.Vector3();
39	const scratchToPlayer3D = new THREE.Vector3();
40	const scratchMobEye = new THREE.Vector3();
41	const scratchPlayerAim = new THREE.Vector3();
42	const scratchRay = new THREE.Vector3();
43	const scratchMobFeet = new THREE.Vector3();
44	const scratchAim = new THREE.Vector3();
45	
46	/**
47	 * A ranged mob looses an arrow from its eye toward the player's chest, leading a
48	 * moving target by a fraction of the arrow's travel time. The arrow is not
49	 * player-owned, so it only ever hits the player (never the firer or other mobs).
50	 */
51	function fireMobArrow(state: GameState, mob: MobState, damage: number, speed: number, emit: EmitGameEvent): void {
52	  const { player } = state;
53	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
54	  const dist = Math.hypot(player.position.x - mob.position.x, player.position.z - mob.position.z);
55	  const lead = (dist / speed) * SKELETON_LEAD_FACTOR;
56	  scratchAim.set(
57	    player.position.x + player.velocity.x * lead - mob.position.x,
58	    player.position.y + 0.9 - eyeY,
59	    player.position.z + player.velocity.z * lead - mob.position.z
60	  );
61	  spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
62	    speed,
63	    damage,
64	    knockback: MOB_ARROW_KNOCKBACK,
65	    fromPlayer: false,
66	    ttl: ARROW_TTL
67	  });
68	  emit({ type: "mobAttacked", kind: mob.kind });
69	}
70	
71	/** The boss looses a 3-arrow horizontal spread aimed at the player's chest. */
72	function fireBossSpread(state: GameState, mob: MobState, dmgScale: number, emit: EmitGameEvent): void {
73	  const { player } = state;
74	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
75	  const baseX = player.position.x - mob.position.x;
76	  const baseY = player.position.y + 0.9 - eyeY;
77	  const baseZ = player.position.z - mob.position.z;
78	  for (let spread = -1; spread <= 1; spread += 1) {
79	    scratchAim.set(baseX, baseY, baseZ);
80	    if (spread !== 0) scratchAim.applyAxisAngle(UP, spread * BOSS_SPREAD);
81	    spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
82	      speed: BOSS_ARROW_SPEED,
83	      damage: BOSS_ARROW_DAMAGE * dmgScale,
84	      knockback: MOB_ARROW_KNOCKBACK,
85	      fromPlayer: false,
86	      ttl: ARROW_TTL
87	    });
88	  }
89	  emit({ type: "mobAttacked", kind: mob.kind });
90	}
91	
92	/**
93	 * The boss periodically conjures a skeleton or zombie nearby while it is engaged,
94	 * up to its own minion cap and the shared global hostile cap.
95	 */
96	function tickBossSummon(state: GameState, mob: MobState, dt: number, deps: MobTickDeps): void {
97	  mob.summonTimer = (mob.summonTimer ?? 0) - dt;
98	  if (mob.summonTimer > 0) return;
99	  mob.summonTimer = BOSS_SUMMON_INTERVAL_SECONDS;
100	
101	  let minions = 0;
102	  let hostiles = 0;
103	  for (const other of state.mobs) {
104	    if (!other.hostile) continue;
105	    hostiles += 1;
106	    if (other.kind !== "boss") minions += 1;
107	  }
108	  if (minions >= BOSS_MINION_CAP || hostiles >= HOSTILE_CAP) return;
109	
110	  const kind = deps.rng() < 0.5 ? "skeleton" : "zombie";
111	  const angle = deps.rng() * Math.PI * 2;
112	  const radius = 2 + deps.rng() * 2;
113	  const mx = mob.position.x + Math.cos(angle) * radius;
114	  const mz = mob.position.z + Math.sin(angle) * radius;
115	  const my = deps.surfaceYAt(mx, mz);
