1	import * as THREE from "three";
2	import {
3	  ARROW_SPEED,
4	  ARROW_TTL,
5	  ATTACK_AIM_DOT,
6	  ATTACK_REACH,
7	  BOW_ARROW_DAMAGE,
8	  BOW_COOLDOWN_SECONDS,
9	  BOW_DURABILITY_PER_SHOT,
10	  BOW_KNOCKBACK,
11	  EYE_HEIGHT,
12	  FIST_DAMAGE,
13	  MELEE_KNOCKBACK_IMPULSE
14	} from "@/lib/game/config";
15	import { adjustSlotCount, consumeToolDurability, countsById } from "@/lib/game/inventory";
16	import { powerBonus, punchKnockback } from "@/lib/game/enchantments";
17	import type { InventorySlot, MobKind } from "@/lib/game/types";
18	import type { EmitGameEvent, GameState } from "../state";
19	import { spawnArrow } from "../projectiles";
20	import { lookDirection } from "./playerMotion";
21	
22	const scratchForward = new THREE.Vector3();
23	const scratchOrigin = new THREE.Vector3();
24	const scratchToMob = new THREE.Vector3();
25	const scratchKnock = new THREE.Vector3();
26	
27	export function weaponDamage(state: GameState): number {
28	  const slot = state.inventory[state.selectedSlot];
29	  if (slot?.kind === "weapon" && slot.count > 0) return slot.attack ?? 8;
30	  return FIST_DAMAGE;
31	}
32	
33	export function weaponReach(state: GameState): number {
34	  const slot = state.inventory[state.selectedSlot];
35	  if (slot?.kind === "weapon" && slot.count > 0) return slot.meleeReach ?? ATTACK_REACH;
36	  return ATTACK_REACH;
37	}
38	
39	/**
40	 * Index of the mob nearest the crosshair within melee reach and aim cone, or
41	 * -1. Shared by attacking and by feeding animals (Phase 5) so both use the same
42	 * "what am I pointing at" rule.
43	 */
44	export function findAimedMobIndex(state: GameState, reach = ATTACK_REACH): number {
45	  const { position } = state.player;
46	  scratchOrigin.set(position.x, position.y + EYE_HEIGHT, position.z);
47	  lookDirection(state.player.yaw, state.player.pitch, scratchForward);
48	
49	  let bestIndex = -1;
50	  let bestDist = Number.POSITIVE_INFINITY;
51	
52	  for (let i = 0; i < state.mobs.length; i += 1) {
53	    const mob = state.mobs[i];
54	    scratchToMob.copy(mob.position).sub(scratchOrigin);
55	    const dist = scratchToMob.length();
56	    if (dist > reach) continue;
57	    scratchToMob.normalize();
58	    if (scratchForward.dot(scratchToMob) < ATTACK_AIM_DOT) continue;
59	    if (dist < bestDist) {
60	      bestDist = dist;
61	      bestIndex = i;
62	    }
63	  }
64	  return bestIndex;
65	}
66	
67	/**
68	 * Melee attack at the mob nearest the crosshair within reach. Returns the kind
69	 * of the mob hit (or null); the caller (engine) handles death drops and durability.
70	 * `knockback` is the extra horizontal impulse from the Knockback enchantment (0 by
71	 * default); `lootingLevel` (the held weapon's Looting) is forwarded to the kill
72	 * callback so the drop roll uses the *killing* weapon, not whatever is held when a
73	 * delayed kill resolves — Looting is a melee enchant, so indirect kills pass 0.
74	 */
75	export function tryAttackMob(
76	  state: GameState,
77	  damage: number,
78	  onMobKilled: (index: number, lootingLevel?: number) => void,
79	  reach = ATTACK_REACH,
80	  knockback = 0,
81	  lootingLevel = 0
82	): MobKind | null {
83	  const { position } = state.player;
84	  const bestIndex = findAimedMobIndex(state, reach);
85	  if (bestIndex < 0) return null;
86	  const mob = state.mobs[bestIndex];
87	  mob.hp -= damage;
88	
89	  scratchKnock.copy(mob.position).sub(position).setY(0);
90	  if (scratchKnock.lengthSq() > 0.0001) {
91	    scratchKnock.normalize();
92	    mob.direction.copy(scratchKnock);
93	    mob.position.addScaledVector(scratchKnock, MELEE_KNOCKBACK_IMPULSE + knockback);
94	    mob.position.y += 0.12;
95	  }
96	
97	  if (mob.hp <= 0) onMobKilled(bestIndex, lootingLevel);
98	  return mob.kind;
99	}
100	
101	/** True when the held slot is a usable bow (the attack input fires instead of melees). */
102	export function isBow(slot: InventorySlot | undefined): boolean {
103	  return slot?.id === "bow" && slot.count > 0;
104	}
105	
106	/**
107	 * Fires one arrow from the player's eye along their look direction, consuming an
108	 * arrow and a point of bow durability and arming the fire-rate cooldown. Returns
109	 * false (no shot) when the bow is on cooldown or the player has no arrows — the
110	 * caller has already confirmed a bow is held via isBow, so a bow never melees.
111	 */
112	export function tryFireBow(state: GameState, emit: EmitGameEvent, rng?: () => number): boolean {
113	  const slot = state.inventory[state.selectedSlot];
114	  if (!isBow(slot)) return false;
115	  if (state.timers.bowCooldownTimer > 0) return false;
116	  if ((countsById(state.inventory).get("arrow") ?? 0) < 1) return false;
117	
118	  const { position, yaw, pitch } = state.player;
119	  scratchOrigin.set(position.x, position.y + EYE_HEIGHT, position.z);
120	  lookDirection(yaw, pitch, scratchForward);
121	  // Power and Punch are bow-only enchants, read off the held bow at the one fire seam.
122	  spawnArrow(state, scratchOrigin.x, scratchOrigin.y, scratchOrigin.z, scratchForward, {
123	    speed: ARROW_SPEED,
124	    damage: BOW_ARROW_DAMAGE + powerBonus(slot),
125	    knockback: BOW_KNOCKBACK + punchKnockback(slot),
126	    fromPlayer: true,
127	    ttl: ARROW_TTL
128	  });
129	
130	  state.inventory = adjustSlotCount(state.inventory, "arrow", -1) ?? state.inventory;
131	  state.inventory = consumeToolDurability(state.inventory, state.selectedSlot, BOW_DURABILITY_PER_SHOT, rng) ?? state.inventory;
132	  state.timers.bowCooldownTimer = BOW_COOLDOWN_SECONDS;
133	  emit({ type: "bowFired" });
134	  return true;
135	}
136

