describe("mobVisuals", () => {
  test("creates one model per mob and removes models for despawned mobs", () => {
    const scene = new THREE.Scene();
    const visuals = createMobVisuals(scene);
    const baseChildren = scene.children.length;

    visuals.sync([makeMob(1), makeMob(2, { kind: "zombie" })], 0);
    expect(scene.children.length).toBe(baseChildren + 2);

    visuals.sync([makeMob(2, { kind: "zombie" })], 0); // mob 1 despawned
    expect(scene.children.length).toBe(baseChildren + 1);

    visuals.dispose();
    expect(scene.children.length).toBe(baseChildren);
  });

  test("reuses the same model across frames for the same mob id", () => {
    const scene = new THREE.Scene();
    const visuals = createMobVisuals(scene);

    visuals.sync([makeMob(7)], 0);
    const group = scene.children[scene.children.length - 1];
    visuals.sync([makeMob(7)], 100);
    expect(scene.children[scene.children.length - 1]).toBe(group);
    visuals.dispose();
  });

  test("applies position, yaw, and a time-varying bob offset", () => {
    const scene = new THREE.Scene();
    const visuals = createMobVisuals(scene);
    const mob = makeMob(1, { yaw: 1.25 });

    visuals.sync([mob], 0);
    const group = scene.children[scene.children.length - 1];
    expect(group.position.x).toBe(10);
    expect(group.position.z).toBe(10);
    expect(group.rotation.y).toBe(1.25);
    expect(Math.abs(group.position.y - 50)).toBeLessThanOrEqual(0.04); // bob amplitude

    const y1 = group.position.y;
    visuals.sync([mob], 100); // quarter of the bob period later
    expect(group.position.y).not.toBe(y1);
    visuals.dispose();
  });

  test("shows current health above hostile mobs and omits it for passive mobs", () => {
    const scene = new THREE.Scene();
    const visuals = createMobVisuals(scene);
    const zombie = makeMob(1, {
      kind: "zombie",
      hostile: true,
      hp: 50,
      halfHeight: mobHalfHeight("zombie")
    });

    visuals.sync([zombie, makeMob(2)], 0);
    const hostileGroup = scene.children[0];
    const passiveGroup = scene.children[1];
    const bar = hostileGroup.getObjectByName("hostile-health-bar");
    const fill = hostileGroup.getObjectByName("hostile-health-fill") as THREE.Sprite;

    expect(bar).toBeDefined();
    expect(bar!.position.y).toBeGreaterThan(MOB_TEMPLATES.zombie.modelArgs[5][1]);
    expect(fill.scale.x).toBeCloseTo(0.45);
    expect(fill.position.x).toBeCloseTo(-0.225);
    expect(passiveGroup.getObjectByName("hostile-health-bar")).toBeUndefined();
    visuals.dispose();
  });
});

import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { BlockId, VoxelWorld } from "@/lib/world";
import { TNT_FUSE_SECONDS } from "@/lib/game/config";
import { createBlockChangeTracker } from "@/lib/game/engine/blockChanges";
import { createTimers, type GameEvent, type GameState, type MobState } from "@/lib/game/engine/state";
import { explode, primeTnt, tickPrimedTnt } from "@/lib/game/engine/systems/explosion";

/** A 24³ world whose lower half is solid dirt — soft blocks the blast can clear. */
function makeWorld(): VoxelWorld {
  const world = new VoxelWorld(24, 24, 24, 1);
  for (let x = 0; x < world.sizeX; x += 1) {
    for (let z = 0; z < world.sizeZ; z += 1) {
      for (let y = 0; y < 12; y += 1) world.set(x, y, z, BlockId.Dirt);
    }
  }
  return world;
}

function makeMob(x: number, y: number, z: number, hp = 20): MobState {
  return {
    id: 1,
    kind: "zombie",
    hostile: true,
    hp,
    position: new THREE.Vector3(x, y, z),
    direction: new THREE.Vector3(1, 0, 0),
    yaw: 0,
    turnTimer: 0,
    speed: 1,
    moveSpeed: 1,
    detectRange: 11,
    attackDamage: 3,
    attackCooldown: 1,
    attackTimer: 0,
    halfHeight: 0.9,
    bobSeed: 0,
    fedTimer: 0,
    ageTimer: 0
  };
}

function makeState(world: VoxelWorld, mobs: MobState[] = []): GameState {
  return {
    world,
    blockChanges: createBlockChangeTracker(world),
    player: { position: new THREE.Vector3(0, 64, 0), velocity: new THREE.Vector3(), yaw: 0, pitch: 0, onGround: true },
    mobs,
    primedTnt: new Map<number, number>(),
    worldMeshDirty: false,
    timers: createTimers()
  } as unknown as GameState;
}

function deps(events: GameEvent[], damages: number[]) {
  return {
    applyDamage: (amount: number) => damages.push(amount),
    rng: () => 0.5,
    emit: (e: GameEvent) => events.push(e)
  };
}

describe("explode — block destruction", () => {
  test("clears a sphere of soft blocks and sets the remesh flag once, emitting one event", () => {
    const world = makeWorld();
    const state = makeState(world);
    const events: GameEvent[] = [];
    explode(state, 8.5, 8.5, 8.5, 3, deps(events, []));

    expect(world.get(8, 8, 8)).toBe(BlockId.Air); // center cleared
    expect(world.get(8, 10, 8)).toBe(BlockId.Air); // distance 2 — solidly inside the blast
    expect(world.get(8, 4, 8)).toBe(BlockId.Dirt); // distance 4 > power 3 — untouched
    expect(state.worldMeshDirty).toBe(true);
    expect(events.filter((e) => e.type === "explosion")).toHaveLength(1);
  });

  test("never breaks bedrock or a spawner inside the blast", () => {
    const world = makeWorld();
    world.set(8, 8, 9, BlockId.Bedrock);
    world.set(9, 8, 8, BlockId.Spawner);
    const state = makeState(world);
    explode(state, 8.5, 8.5, 8.5, 3, deps([], []));

    expect(world.get(8, 8, 9)).toBe(BlockId.Bedrock);
    expect(world.get(9, 8, 8)).toBe(BlockId.Spawner);
  });
});

describe("explode — damage falloff", () => {
  test("damages the player most at the center and less at the edge", () => {
    const near: number[] = [];
    const far: number[] = [];
    const sNear = makeState(makeWorld());
    sNear.player.position.set(8.5, 8.5, 8.5);
    explode(sNear, 8.5, 8.5, 8.5, 3, deps([], near));

    const sFar = makeState(makeWorld());
    sFar.player.position.set(8.5 + 5, 8.5, 8.5); // dist 5, within range (power*2 = 6)
    explode(sFar, 8.5, 8.5, 8.5, 3, deps([], far));

    expect(near[0]).toBeGreaterThan(far[0]);
    expect(far[0]).toBeGreaterThanOrEqual(1); // still inside the damage radius
  });

  test("leaves a player outside the damage radius unharmed and applies knockback inside it", () => {
    const damages: number[] = [];
    const state = makeState(makeWorld());
    state.player.position.set(8.5 + 7, 8.5, 8.5); // dist 7 > power*2 = 6
    explode(state, 8.5, 8.5, 8.5, 3, deps([], damages));
    expect(damages).toHaveLength(0);

    const hit = makeState(makeWorld());
    hit.player.position.set(8.5 + 2, 8.5, 8.5);
    explode(hit, 8.5, 8.5, 8.5, 3, deps([], []));
    expect(hit.player.velocity.x).toBeGreaterThan(0); // shoved away from the blast
  });

  test("damages mobs in range without removing them (caller sweeps the dead)", () => {
    const mob = makeMob(9.5, 8.5, 8.5, 20);
    const state = makeState(makeWorld(), [mob]);
    explode(state, 8.5, 8.5, 8.5, 3, deps([], []));
    expect(mob.hp).toBeLessThan(20);
    expect(state.mobs).toHaveLength(1); // explode only lowers hp; it never splices
  });
});

describe("primed TNT", () => {
  test("primeTnt lights a fuse and tickPrimedTnt detonates it when the fuse runs out", () => {
    const world = makeWorld();
    world.set(8, 12, 8, BlockId.Tnt); // a TNT block sitting on the dirt
    const state = makeState(world);
    const events: GameEvent[] = [];
    const d = deps(events, []);

    primeTnt(state, 8, 12, 8, d.emit);
    expect(state.primedTnt.size).toBe(1);
    expect(events.some((e) => e.type === "tntPrimed")).toBe(true);

    tickPrimedTnt(state, TNT_FUSE_SECONDS - 0.1, d); // not yet
    expect(state.primedTnt.size).toBe(1);
    expect(world.get(8, 12, 8)).toBe(BlockId.Tnt);

    tickPrimedTnt(state, 0.2, d); // fuse expires
    expect(world.get(8, 12, 8)).toBe(BlockId.Air);
    expect(state.primedTnt.size).toBe(0);
    expect(events.some((e) => e.type === "explosion")).toBe(true);
  });

  test("a blast chains adjacent TNT by lighting it rather than vaporizing it", () => {
    const world = makeWorld();
    world.set(10, 12, 8, BlockId.Tnt); // adjacent to the blast, within radius
    const state = makeState(world);
    explode(state, 9.5, 12.5, 8.5, 4, deps([], []));

    // The neighboring TNT survives the blast but is now primed (will blow next).
    expect(world.get(10, 12, 8)).toBe(BlockId.Tnt);
    expect(state.primedTnt.has(world.index(10, 12, 8))).toBe(true);
  });

  test("a primed TNT block that was mined away never detonates", () => {
    const world = makeWorld();
    world.set(8, 12, 8, BlockId.Tnt);
    const state = makeState(world);
    primeTnt(state, 8, 12, 8, () => {});
    world.set(8, 12, 8, BlockId.Air); // mined before the fuse ran out

    const events: GameEvent[] = [];
    tickPrimedTnt(state, TNT_FUSE_SECONDS + 1, deps(events, []));
    expect(state.primedTnt.size).toBe(0);
    expect(events.some((e) => e.type === "explosion")).toBe(false);
  });
});

import { describe, expect, test } from "bun:test";
import * as THREE from "three";
import { BlockId, VoxelWorld } from "@/lib/world";
import { spawnArrow } from "@/lib/game/engine/projectiles";
import { tickProjectiles } from "@/lib/game/engine/systems/projectileAI";
import type { GameEvent, GameState, MobState } from "@/lib/game/engine/state";

function makeMob(id: number, x: number, y: number, z: number, hp = 10, halfHeight = 0.5): MobState {
  return {
    id,
    kind: "zombie",
    hostile: true,
    hp,
    position: new THREE.Vector3(x, y, z),
    direction: new THREE.Vector3(0, 0, 1),
    yaw: 0,
    turnTimer: 0,
    speed: 1,
    moveSpeed: 1,
    detectRange: 11,
    attackDamage: 3,
    attackCooldown: 1,
    attackTimer: 0,
    halfHeight,
    bobSeed: 0,
    fedTimer: 0,
    ageTimer: 0
  };
}

function makeState(world: VoxelWorld, mobs: MobState[] = []): GameState {
  return {
    world,
    mobs,
    projectiles: [],
    nextProjectileId: 1,
    player: { position: new THREE.Vector3(16, 14, 16), velocity: new THREE.Vector3(), yaw: 0, pitch: 0, onGround: true }
  } as unknown as GameState;
}

function makeDeps() {
  const events: GameEvent[] = [];
  const removed: number[] = [];
  let damage = 0;
  const deps = {
    applyDamage: (a: number) => {
      damage += a;
    },
    removeMobAt: (i: number) => {
      removed.push(i);
    },
    emit: (e: GameEvent) => {
      events.push(e);
    }
  };
  return { deps, events, removed, getDamage: () => damage };
}

function tickUntilGone(state: GameState, deps: ReturnType<typeof makeDeps>["deps"], max = 400): number {
  let n = 0;
  while (state.projectiles.length > 0 && n < max) {
    tickProjectiles(state, 0.05, deps);
    n += 1;
  }
  return n;
}

describe("tickProjectiles", () => {
  test("arrows arc downward under gravity and despawn at ttl", () => {
    const world = new VoxelWorld(32, 32, 32, 1);
    const state = makeState(world);
    const { deps } = makeDeps();
    const arrow = spawnArrow(state, 16, 20, 16, new THREE.Vector3(0, 0, -1), { speed: 20, damage: 5, knockback: 0.3, fromPlayer: true, ttl: 0.2 });

    tickProjectiles(state, 0.05, deps);
    tickProjectiles(state, 0.05, deps);
    expect(arrow.position.z).toBeLessThan(16); // travelled along -z
    expect(arrow.velocity.y).toBeLessThan(0); // gravity pulled it down
    expect(arrow.position.y).toBeLessThan(20);

    tickProjectiles(state, 0.05, deps);
    tickProjectiles(state, 0.05, deps);
    tickProjectiles(state, 0.05, deps);
    expect(state.projectiles).toHaveLength(0); // ttl elapsed
  });

  test("an arrow sticks/despawns when it hits a wall", () => {
    const world = new VoxelWorld(32, 32, 32, 1);
    for (let y = 14; y <= 18; y += 1) for (let x = 14; x <= 18; x += 1) world.set(x, y, 10, BlockId.Stone);
    const state = makeState(world);
    const { deps, events } = makeDeps();
    spawnArrow(state, 16, 16, 16, new THREE.Vector3(0, 0, -1), { speed: 34, damage: 5, knockback: 0.3, fromPlayer: true, ttl: 4 });

    tickUntilGone(state, deps);
    expect(state.projectiles).toHaveLength(0);
    const blockHit = events.find((e) => e.type === "arrowHit" && e.target === "block");
    expect(blockHit).toBeDefined();
    if (blockHit && blockHit.type === "arrowHit") expect(blockHit.z).toBeLessThanOrEqual(11);
  });

  test("a very fast arrow still registers a 1-block-thick wall (no tunnelling)", () => {
    const world = new VoxelWorld(32, 32, 32, 1);
    world.set(12, 12, 10, BlockId.Stone); // single solid cell
    const state = makeState(world);
    const { deps, events } = makeDeps();
    // 400 m/s × 0.05 s = 20 blocks/step — would skip the wall without the swept DDA.
    // x/y at .3 keep the ray off the integer cell boundaries (avoids a DDA tie-break).
    spawnArrow(state, 12.3, 12.3, 12, new THREE.Vector3(0, 0, -1), { speed: 400, damage: 5, knockback: 0, fromPlayer: true, ttl: 4 });

    tickProjectiles(state, 0.05, deps);
    expect(state.projectiles).toHaveLength(0);
    expect(events.some((e) => e.type === "arrowHit" && e.target === "block")).toBe(true);
  });

  test("a player arrow damages and knocks back a mob, killing it when lethal", () => {
    const world = new VoxelWorld(32, 32, 32, 1);
    const mob = makeMob(1, 16, 16, 12, 10);
    const state = makeState(world, [mob]);
    const { deps, events, removed } = makeDeps();
    spawnArrow(state, 16, 16, 16, new THREE.Vector3(0, 0, -1), { speed: 34, damage: 9, knockback: 0.75, fromPlayer: true, ttl: 4 });

    tickUntilGone(state, deps);
    expect(mob.hp).toBe(1);
    expect(mob.position.z).toBeLessThan(12); // knocked along the arrow's -z travel
    expect(events.some((e) => e.type === "mobHit")).toBe(true);
    expect(events.some((e) => e.type === "arrowHit" && e.target === "mob")).toBe(true);
    expect(removed).toHaveLength(0);

    // A lethal shot triggers removeMobAt.
    const lethalMob = makeMob(2, 16, 16, 12, 5);
    const lethalState = makeState(world, [lethalMob]);
    const lethalDeps = makeDeps();
    spawnArrow(lethalState, 16, 16, 16, new THREE.Vector3(0, 0, -1), { speed: 34, damage: 9, knockback: 0.75, fromPlayer: true, ttl: 4 });
    tickUntilGone(lethalState, lethalDeps.deps);
    expect(lethalDeps.removed).toEqual([0]);
  });

  test("the fromPlayer filter routes hits: player arrows ignore the player, mob arrows ignore mobs", () => {
    // Mob arrow toward the player: damages the player, ignores other mobs.
    const world = new VoxelWorld(32, 32, 32, 1);
    const bystander = makeMob(1, 16, 14, 18, 10);
    const state = makeState(world, [bystander]);
    const { deps, getDamage } = makeDeps();
    spawnArrow(state, 16, 14.9, 20, new THREE.Vector3(0, 0, -1), { speed: 34, damage: 6, knockback: 0.4, fromPlayer: false, ttl: 4 });
