        let scale = mob.ageTimer > 0 ? BABY_SCALE : 1;
        if (mob.kind === "creeper") {
          const primed = (mob.fuseTimer ?? 0) > 0;
          const wave = 0.5 + 0.5 * Math.sin(timeMs * 0.025);
