11	function mulberry32(seed: number): () => number {
12	  let t = seed >>> 0;
13	  return () => {
14	    t += 0x6d2b79f5;
15	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
16	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
17	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
18	  };
19	}
