69	function memoryStorage(initial: Record<string, string> = {}): Storage {
70	  const data = new Map(Object.entries(initial));
71	  return {
72	    get length() {
73	      return data.size;
74	    },
75	    clear: () => data.clear(),
76	    getItem: (key: string) => data.get(key) ?? null,
77	    key: (index: number) => [...data.keys()][index] ?? null,
78	    removeItem: (key: string) => void data.delete(key),
79	    setItem: (key: string, value: string) => void data.set(key, value)
80	  };
81	}
