describe("villager trading", () => {
  test("right-clicking a villager opens its trades, which only craft while open", () => {
    const engine = makeEngine();
    calmDaytime(engine);
    engine.state.mobs = [];
    run(engine, 1);
    const { state } = engine;
    state.player.yaw = 0;
    state.player.pitch = 0;

    // A villager standing in the crosshair, two blocks ahead at eye height.
    const p = state.player.position;
    state.mobs.push({
      id: state.nextMobId++,
      kind: "villager",
      hostile: false,
      faction: "villager",
      targetId: null,
      retargetTimer: 0,
      hp: 20,
      position: new THREE.Vector3(p.x, p.y + EYE_HEIGHT, p.z - 2),
      direction: new THREE.Vector3(0, 0, 1),
      yaw: 0,
      turnTimer: 9,
      speed: 0,
      moveSpeed: 0,
      detectRange: 0,
      attackDamage: 0,
      attackCooldown: 0,
      attackTimer: 0,
      halfHeight: 0.9,
      bobSeed: 0,
      fedTimer: 0,
      ageTimer: 0
    });

    // A villager trade is refused while no villager is open.
    const slot = state.inventory.findIndex((s) => !s.id);
