68	    const world = new VoxelWorld(64, 64, 64, 1);
69	    generateWorld(world);
70	    const state = { world, mobs: [], nextMobId: 1 } as unknown as GameState;
71	    spawnVillageResidents(state, [{ x: 20, z: 20 }], mulberry32(1), createSurfaceYAt(world));
72	    state.mobs[0].profession = "cleric"; // a "restored" resident keeps its profession
73	
74	    assignVillagerProfessions(state);
75	
76	    expect(state.mobs[0].profession).toBe("cleric"); // untouched
77	    expect(state.mobs.slice(1).map((m) => m.profession)).toEqual(PROFESSIONS.slice(0, state.mobs.length - 1)); // the rest cycle
78	  });
79	});
80	
81	describe("tickHostileSpawnDirector", () => {
82	  /** Puts the world at night with the spawn timer already past any interval. */
83	  function primeForSpawn(e: GameEngine): void {
84	    e.state.mobs = [];
85	    e.state.daylight = 0.1; // below HOSTILE_SPAWN_BELOW_DAYLIGHT
86	    e.state.timers.hostileSpawnTimer = 1000;
87	  }
88	
89	  test("Peaceful never trickles a hostile, even at night past the interval", () => {
90	    const e = makeEngine("peaceful");
91	    primeForSpawn(e);
92	    tickHostileSpawnDirector(e.state, 0.1, mulberry32(3), createSurfaceYAt(e.state.world));
93	    expect(hostileCount(e)).toBe(0);
94	  });
95	
96	  test("Normal trickles at least one hostile under the same conditions", () => {
97	    const e = makeEngine("normal");
98	    primeForSpawn(e);
99	    tickHostileSpawnDirector(e.state, 0.1, mulberry32(3), createSurfaceYAt(e.state.world));
100	    expect(hostileCount(e)).toBeGreaterThan(0);
101	  });
102	
103	  test("Hard honours its raised cap (16 × 1.5 = 24): no spawn once full", () => {
104	    const e = makeEngine("hard");
105	    primeForSpawn(e);
106	    const { x, y, z } = e.state.player.position;
107	    const rng = mulberry32(9);
108	    for (let i = 0; i < 24; i += 1) pushMob(e.state, "zombie", true, x + (i % 5), y, z + i, rng);
109	    tickHostileSpawnDirector(e.state, 0.1, rng, createSurfaceYAt(e.state.world));
110	    expect(hostileCount(e)).toBe(24); // already at the Hard cap — nothing added
111	  });
112	
113	  test("Easy's lowered cap (16 × 0.5 = 8) blocks spawns the Normal cap would allow", () => {
114	    const e = makeEngine("easy");
115	    primeForSpawn(e);
116	    const { x, y, z } = e.state.player.position;
117	    const rng = mulberry32(11);
118	    for (let i = 0; i < 8; i += 1) pushMob(e.state, "zombie", true, x + (i % 4), y, z + i, rng);
119	    expect(8).toBeLessThan(HOSTILE_CAP); // would still be under the baseline cap
120	    tickHostileSpawnDirector(e.state, 0.1, rng, createSurfaceYAt(e.state.world));
121	    expect(hostileCount(e)).toBe(8); // but Easy is already capped
122	  });
123	
124	  test("at cap-1, a rolled 2-pack is clamped so the cap is never overshot", () => {
125	    const e = makeEngine("easy"); // cap 8 — the tightest, so the 2-pack edge bites soonest
126	    // Sweep seeds so at least one roll is a 2-pack: without the count clamp, that
127	    // seed would push 7 → 9 and overshoot; the clamp holds every seed at ≤ 8.
128	    for (let seed = 1; seed <= 12; seed += 1) {
129	      e.state.mobs = [];
130	      const { x, y, z } = e.state.player.position;
131	      const seeder = mulberry32(100 + seed);
132	      for (let i = 0; i < 7; i += 1) pushMob(e.state, "zombie", true, x + (i % 4), y, z + i, seeder); // cap - 1
133	      e.state.daylight = 0.1;
134	      e.state.timers.hostileSpawnTimer = 1000;
135	      tickHostileSpawnDirector(e.state, 0.1, mulberry32(seed), createSurfaceYAt(e.state.world));
136	      expect(hostileCount(e)).toBeLessThanOrEqual(8);
137	    }
138	  });
139	});
140	
141	describe("tickSpawnerDirector", () => {
142	  test("Peaceful keeps dungeon spawners inert", () => {
143	    const e = makeEngine("peaceful");
144	    e.state.mobs = [];
145	    // Pretend a spawner is active right on top of the player; Peaceful returns first.
146	    e.state.dungeonSpawnerIndices = new Set([0]);
147	    e.state.timers.spawnerTimer = 1000;
148	    tickSpawnerDirector(e.state, 0.1, mulberry32(5), () => {});
149	    expect(hostileCount(e)).toBe(0);
150	  });
151	});

