toolUseResult.originalFile:
import { LOOTING_BONUS_PER_LEVEL } from "@/lib/game/config";
import type { MobKind } from "@/lib/game/types";

/**
 * A single loot entry: yields a uniformly random count in [min, max], gated by
 * an optional drop chance (default: always). Counts are inclusive on both ends.
 */
export type MobDrop = {
  itemId: string;
  min: number;
  max: number;
  /** 0..1 probability the entry drops at all; omitted means always. */
  chance?: number;
};

/**
 * What each mob drops when it dies. Hostiles yield crafting/combat materials,
 * passives yield materials plus raw meat. Item ids must exist in ITEM_DEFS —
 * mobLoot.test.ts enforces that.
 */
export const MOB_DROPS: Record<MobKind, MobDrop[]> = {
  sheep: [
    { itemId: "wool", min: 1, max: 2 },
    { itemId: "raw_mutton", min: 1, max: 1 }
  ],
  chicken: [
    { itemId: "feather", min: 0, max: 2 },
    { itemId: "raw_chicken", min: 1, max: 1 }
  ],
  horse: [{ itemId: "leather", min: 1, max: 2 }],
  cow: [
    { itemId: "leather", min: 1, max: 2 },
    { itemId: "raw_beef", min: 1, max: 1 }
  ],
  pig: [{ itemId: "raw_porkchop", min: 1, max: 1 }],
  // Pets drop nothing — you don't harvest your companions. Empty tables are allowed.
  wolf: [],
  cat: [],
  zombie: [{ itemId: "rotten_flesh", min: 1, max: 2 }],
  skeleton: [{ itemId: "bone", min: 1, max: 2 }],
  spider: [{ itemId: "string", min: 0, max: 2 }],
  creeper: [{ itemId: "gunpowder", min: 1, max: 2 }],
  // Villagers are non-combat trade NPCs — killing one yields nothing (don't murder
  // your shopkeeper). The empty table is intentional; mobLoot.test.ts allows it.
  villager: [],
  boss: [
    { itemId: "dragon_heart", min: 1, max: 1 },
    { itemId: "diamond_ore", min: 2, max: 4 }
  ]
};

/** Clamps an rng sample into [0, 1) so a pathological injected rng can't over-roll. */
const clampUnit = (v: number): number => Math.min(1 - Number.EPSILON, Math.max(0, v));

/**
 * Rolls the drop table for a mob kind. Returns one entry per item that yielded a
 * positive count; the engine adds each to the inventory. `rng` is injectable so
 * tests get deterministic counts (0 → min, ~1 → max). `lootingLevel` (from the
 * Looting enchantment on the killing weapon) adds a random bonus count — up to
 * `level × LOOTING_BONUS_PER_LEVEL` extra — to each entry that already dropped.
 */
export function rollMobDrops(kind: MobKind, rng: () => number, lootingLevel = 0): Array<{ itemId: string; count: number }> {
  const drops: Array<{ itemId: string; count: number }> = [];
  for (const entry of MOB_DROPS[kind]) {
    if (entry.chance !== undefined && clampUnit(rng()) >= entry.chance) continue;
    const span = entry.max - entry.min + 1;
    let count = entry.min + Math.floor(clampUnit(rng()) * span);
    if (count > 0 && lootingLevel > 0) {
      count += Math.floor(clampUnit(rng()) * (lootingLevel * LOOTING_BONUS_PER_LEVEL + 1));
    }
    if (count > 0) drops.push({ itemId: entry.itemId, count });
  }
  return drops;
}

import type { MobKind } from "@/lib/game/types";

/**
 * XP granted for killing each mob kind. Hostiles reward more than passives, and
 * the boss is a jackpot. Mirrors `mobLoot.ts`; the exhaustive `Record<MobKind>`
 * means a new mob can't silently grant no XP, and `xp.test.ts` checks the shape.
 */
export const MOB_XP: Record<MobKind, number> = {
  sheep: 1,
  chicken: 1,
  horse: 2,
  cow: 2,
  pig: 1,
  // Companions yield no XP — paired with their empty drop tables, killing a pet
  // (or a wild wolf/cat) is never rewarded, so they can't be farmed.
  wolf: 0,
  cat: 0,
  // A villager is a trade NPC — no combat reward (and you shouldn't be killing it).
  villager: 0,
  zombie: 5,
  skeleton: 5,
  spider: 5,
  creeper: 5,
  boss: 200
};

export function xpForMob(kind: MobKind): number {
  return MOB_XP[kind];
}

import type { MobKind } from "@/lib/game/types";

/** Mobs farther than this are silent. */
export const MOB_EARSHOT = 24;

/** Seconds between idle calls per kind (min..max, uniform). */
const CALL_INTERVALS: Record<MobKind, readonly [number, number]> = {
  sheep: [6, 14],
  chicken: [5, 12],
  horse: [8, 18],
  cow: [7, 16],
  pig: [5, 13],
  wolf: [5, 12],
  cat: [6, 14],
  zombie: [4, 9],
  skeleton: [5, 11],
  spider: [4, 10],
  creeper: [6, 13],
  villager: [7, 15],
  boss: [6, 12]
};

/** Structural subset of the engine's MobState — state.mobs passes directly. */
export type AmbientMob = {
  id: number;
  kind: MobKind;
  position: { x: number; z: number };
};

export type AmbientCall = {
  kind: MobKind;
  /** Distance falloff 0..1. */
  gain: number;
  /** Stereo position -1..1 relative to the player's look direction. */
  pan: number;
};

export type MobAmbienceScheduler = {
  /** Returns calls due this frame. The array is reused — consume immediately. */
  tick(dt: number, mobs: readonly AmbientMob[], playerX: number, playerZ: number, playerYaw: number): readonly AmbientCall[];
};

export function createMobAmbienceScheduler(rng: () => number = Math.random): MobAmbienceScheduler {
  const timers = new Map<number, number>();
  const calls: AmbientCall[] = [];

  const nextInterval = (kind: MobKind): number => {
    const [min, max] = CALL_INTERVALS[kind];
    return min + rng() * (max - min);
  };

  return {
    tick(dt, mobs, playerX, playerZ, playerYaw) {
      calls.length = 0;

      // Despawned mobs leave stale timers behind; sweep once the map outgrows
      // the population instead of allocating an id set every frame.
      if (timers.size > mobs.length + 8) {
        const alive = new Set(mobs.map((mob) => mob.id));
        for (const id of timers.keys()) if (!alive.has(id)) timers.delete(id);
      }

      const rightX = Math.cos(playerYaw);
      const rightZ = -Math.sin(playerYaw);

      for (const mob of mobs) {
        const dx = mob.position.x - playerX;
        const dz = mob.position.z - playerZ;
        const dist = Math.hypot(dx, dz);
        if (dist > MOB_EARSHOT) continue;

        const timer = timers.get(mob.id);
        if (timer === undefined) {
          // First sighting: start a full randomized interval so a spawn wave
          // doesn't open with a chorus.
          timers.set(mob.id, nextInterval(mob.kind));
          continue;
        }
        const remaining = timer - dt;
        if (remaining > 0) {
          timers.set(mob.id, remaining);
          continue;
        }
        timers.set(mob.id, nextInterval(mob.kind));

        const falloff = 1 - dist / MOB_EARSHOT;
        const pan = dist > 0.001 ? Math.max(-1, Math.min(1, (dx * rightX + dz * rightZ) / dist)) : 0;
        calls.push({ kind: mob.kind, gain: falloff * falloff, pan });
      }
      return calls;
    }
  };
}

